import{_ as a,a as s,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第53–59课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第53–59课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第46–52课","link":"/life/english/new-concept/book-1/review-part-07"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第60–66课","link":"/life/english/new-concept/book-1/review-part-09"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第46–52课","link":"/life/english/new-concept/book-1/review-part-07"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第60–66课","link":"/life/english/new-concept/book-1/review-part-09"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-08.md","filePath":"life/english/new-concept/book-1/review-part-08.md"}'),t={name:"life/english/new-concept/book-1/review-part-08.md"};function l(r,e,i,p,c,h){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第53–59课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第53–59课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第53–59课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第53–59课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-53-·-频率副词与天气动词" tabindex="-1">Lesson 53 · 频率副词与天气动词 <a class="header-anchor" href="#lesson-53-·-频率副词与天气动词" aria-label="Permalink to &quot;Lesson 53 · 频率副词与天气动词 {#lesson-53-·-频率副词与天气动词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> It often rains in this coastal town.</p><h3 id="练习-1-52" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-52" aria-label="Permalink to &quot;练习 1 {#练习-1-52}&quot;">​</a></h3><p>选择 rain/rains：It often ___ here.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> rains</p><p><strong>解析：</strong> 按本课规则判断：always、usually、often、sometimes、never 表频率，通常位于实义动词前、be 后。It often rains 中 rain 是动词；It is often rainy 中 rainy 是形容词。频率不等于眼前进行：often rains 描述规律，is raining 描述此刻。never 已含否定意义，在标准英语中通常不再配 don&#39;t。</p></details><p><strong>表达迁移：</strong> 围绕“比较季节天气并询问来自哪里”写两至三句，再读给同伴听。至少使用一次频率副词与天气动词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>It often rains in this coastal town. The evenings are usually cool in autumn.</p><p>It 是天气主语，rains 是实义动词第三人称形式；often 在实义动词之前，in this coastal town 是地点。 The evenings 是复数主语，are 后放 usually，cool 作表语；in autumn 表季节。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-053">回看本课</a></p><h2 id="lesson-54-·-频率副词与天气动词" tabindex="-1">Lesson 54 · 频率副词与天气动词 <a class="header-anchor" href="#lesson-54-·-频率副词与天气动词" aria-label="Permalink to &quot;Lesson 54 · 频率副词与天气动词 {#lesson-54-·-频率副词与天气动词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The evenings are usually cool in autumn.</p><h3 id="练习-1-53" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-53" aria-label="Permalink to &quot;练习 1 {#练习-1-53}&quot;">​</a></h3><p>给 usually 排序：The evenings / are / cool / usually.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The evenings are usually cool.</p><p><strong>解析：</strong> 按本课规则判断：always、usually、often、sometimes、never 表频率，通常位于实义动词前、be 后。It often rains 中 rain 是动词；It is often rainy 中 rainy 是形容词。频率不等于眼前进行：often rains 描述规律，is raining 描述此刻。never 已含否定意义，在标准英语中通常不再配 don&#39;t。</p></details><p><strong>表达迁移：</strong> 围绕“比较季节天气并询问来自哪里”写两至三句，再读给同伴听。至少使用一次频率副词与天气动词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The evenings are usually cool in autumn. It often rains in this coastal town.</p><p>The evenings 是复数主语，are 后放 usually，cool 作表语；in autumn 表季节。 It 是天气主语，rains 是实义动词第三人称形式；often 在实义动词之前，in this coastal town 是地点。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-054">回看本课</a></p><h2 id="lesson-55-·-一般现在时的习惯动作" tabindex="-1">Lesson 55 · 一般现在时的习惯动作 <a class="header-anchor" href="#lesson-55-·-一般现在时的习惯动作" aria-label="Permalink to &quot;Lesson 55 · 一般现在时的习惯动作 {#lesson-55-·-一般现在时的习惯动作}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My father leaves home at half past seven.</p><h3 id="练习-1-54" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-54" aria-label="Permalink to &quot;练习 1 {#练习-1-54}&quot;">​</a></h3><p>填动词：My father ___ (leave) home early.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> leaves</p><p><strong>解析：</strong> 按本课规则判断：一般现在时描述习惯、规律和相对稳定状态。谈家庭成员时要逐个检查主语：parents 用 go，father 用 goes。时间表达可用 at seven、in the evening、on Mondays。通常活动不必加 now，now 更容易指向正在进行。every day 是时间短语，everyday 是形容词，修饰日常事物。</p></details><p><strong>表达迁移：</strong> 围绕“介绍一家人的每日作息”写两至三句，再读给同伴听。至少使用一次一般现在时的习惯动作，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My father leaves home at half past seven. We usually cook dinner together.</p><p>My father 为第三人称单数，所以用 leaves；home 在 leave home 中表示离开家，at half past seven 表钟点。 We 为复数主语，cook 用原形；usually 放在实义动词前，together 表示一起完成动作。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-055">回看本课</a></p><h2 id="lesson-56-·-一般现在时的习惯动作" tabindex="-1">Lesson 56 · 一般现在时的习惯动作 <a class="header-anchor" href="#lesson-56-·-一般现在时的习惯动作" aria-label="Permalink to &quot;Lesson 56 · 一般现在时的习惯动作 {#lesson-56-·-一般现在时的习惯动作}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We usually cook dinner together.</p><h3 id="练习-1-55" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-55" aria-label="Permalink to &quot;练习 1 {#练习-1-55}&quot;">​</a></h3><p>选择 at/in：___ half past seven.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> at</p><p><strong>解析：</strong> 按本课规则判断：一般现在时描述习惯、规律和相对稳定状态。谈家庭成员时要逐个检查主语：parents 用 go，father 用 goes。时间表达可用 at seven、in the evening、on Mondays。通常活动不必加 now，now 更容易指向正在进行。every day 是时间短语，everyday 是形容词，修饰日常事物。</p></details><p><strong>表达迁移：</strong> 围绕“介绍一家人的每日作息”写两至三句，再读给同伴听。至少使用一次一般现在时的习惯动作，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We usually cook dinner together. My father leaves home at half past seven.</p><p>We 为复数主语，cook 用原形；usually 放在实义动词前，together 表示一起完成动作。 My father 为第三人称单数，所以用 leaves；home 在 leave home 中表示离开家，at half past seven 表钟点。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-056">回看本课</a></p><h2 id="lesson-57-·-一般现在时与现在进行时" tabindex="-1">Lesson 57 · 一般现在时与现在进行时 <a class="header-anchor" href="#lesson-57-·-一般现在时与现在进行时" aria-label="Permalink to &quot;Lesson 57 · 一般现在时与现在进行时 {#lesson-57-·-一般现在时与现在进行时}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I usually cycle to work, but today I am taking the bus.</p><h3 id="练习-1-56" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-56" aria-label="Permalink to &quot;练习 1 {#练习-1-56}&quot;">​</a></h3><p>填动词：I usually ___ (cycle) to work.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> cycle</p><p><strong>解析：</strong> 按本课规则判断：一般现在时说明通常怎样，现在进行时说明现在正在怎样。对比段落可用 usually 与 today/now 建立时间框架。选择时态要看动作意义，而非看到 today 就一律进行时。like、know 等状态动词通常不用进行时表达普通状态。现在进行时既要有 be，也要有动词 ing。</p></details><p><strong>表达迁移：</strong> 围绕“对比平时安排和今天的变化”写两至三句，再读给同伴听。至少使用一次一般现在时与现在进行时，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I usually cycle to work, but today I am taking the bus. Leo is wearing a suit now.</p><p>Usually cycle 说明惯常出行；but 连接对比，today I am taking the bus 描述今天的临时安排或进行中的出行。 Leo 是单数主语，is wearing 描述此刻穿着；wear 表穿着状态，a suit 为宾语，now 给出当前时间。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-057">回看本课</a></p><h2 id="lesson-58-·-一般现在时与现在进行时" tabindex="-1">Lesson 58 · 一般现在时与现在进行时 <a class="header-anchor" href="#lesson-58-·-一般现在时与现在进行时" aria-label="Permalink to &quot;Lesson 58 · 一般现在时与现在进行时 {#lesson-58-·-一般现在时与现在进行时}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Leo is wearing a suit now.</p><h3 id="练习-1-57" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-57" aria-label="Permalink to &quot;练习 1 {#练习-1-57}&quot;">​</a></h3><p>填 be：Leo ___ wearing a suit now.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：一般现在时说明通常怎样，现在进行时说明现在正在怎样。对比段落可用 usually 与 today/now 建立时间框架。选择时态要看动作意义，而非看到 today 就一律进行时。like、know 等状态动词通常不用进行时表达普通状态。现在进行时既要有 be，也要有动词 ing。</p></details><p><strong>表达迁移：</strong> 围绕“对比平时安排和今天的变化”写两至三句，再读给同伴听。至少使用一次一般现在时与现在进行时，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Leo is wearing a suit now. I usually cycle to work, but today I am taking the bus.</p><p>Leo 是单数主语，is wearing 描述此刻穿着；wear 表穿着状态，a suit 为宾语，now 给出当前时间。 Usually cycle 说明惯常出行；but 连接对比，today I am taking the bus 描述今天的临时安排或进行中的出行。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-058">回看本课</a></p><h2 id="lesson-59-·-可数和不可数名词的数量" tabindex="-1">Lesson 59 · 可数和不可数名词的数量 <a class="header-anchor" href="#lesson-59-·-可数和不可数名词的数量" aria-label="Permalink to &quot;Lesson 59 · 可数和不可数名词的数量 {#lesson-59-·-可数和不可数名词的数量}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We need five envelopes and some writing paper.</p><h3 id="练习-1-58" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-58" aria-label="Permalink to &quot;练习 1 {#练习-1-58}&quot;">​</a></h3><p>选择 much/many：How ___ envelopes?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> many</p><p><strong>解析：</strong> 按本课规则判断：可数名词用 many、a few 或具体数词，通常有复数形式；不可数名词用 much、a little 或量词。some 可用于两者。have 作拥有的实义动词时，否定可用 don&#39;t have。购物清单中 a kilo of apples 的数量核心是 kilo，复数时写 two kilos of apples。不要把中文数量词直接省略。</p></details><p><strong>表达迁移：</strong> 围绕“核对购物清单并表达数量”写两至三句，再读给同伴听。至少使用一次可数和不可数名词的数量，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We need five envelopes and some writing paper. How much flour do you need?</p><p>Need 的宾语由 five envelopes 和 some writing paper 并列组成：前者可数复数，后者不可数。 How much flour 是疑问宾语，flour 不可数；do 放在主语 you 之前，need 用原形。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-059">回看本课</a></p>',60)])])}const m=a(t,[["render",l]]);export{d as __pageData,m as default};
